import React,{useState} from 'react';import {supabase} from '../lib/supabase';import {useAuth} from '../contexts/AuthContext';import toast from 'react-hot-toast';import {Lock,X} from 'lucide-react';
export default function PinSetup({onSuccess,onClose}){const {staff,reloadStaff,markPinPromptAsShown}=useAuth();const [pin,setPin]=useState('');const [confirm,setConfirm]=useState('');const [loading,setLoading]=useState(false);const handleSubmit=async e=>{e.preventDefault();if(pin.length!==4||!/^\d+$/.test(pin))return toast.error('PIN must be 4 digits');if(pin!==confirm)return toast.error('PINs do not match');setLoading(true);try{await supabase.from('staff').update({pin_code:pin}).eq('id',staff.id);toast.success('PIN set');markPinPromptAsShown();await reloadStaff();onSuccess();}catch(err){toast.error(err.message)}finally{setLoading(false);}};return(<div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"><div className="bg-white rounded-2xl w-full max-w-sm"><div className="p-4 border-b flex justify-between"><h2 className="font-bold"><Lock className="inline mr-2" size={18}/>Set Your PIN</h2><button onClick={()=>{markPinPromptAsShown();onClose();}}><X/></button></div><form onSubmit={handleSubmit} className="p-4 space-y-4"><input type="password" maxLength="4" placeholder="Enter 4-digit PIN" value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,''))} className="w-full p-4 border rounded-lg text-center text-2xl" autoFocus/><input type="password" maxLength="4" placeholder="Confirm PIN" value={confirm} onChange={e=>setConfirm(e.target.value.replace(/\D/g,''))} className="w-full p-4 border rounded-lg text-center text-2xl"/><button disabled={loading} className="w-full bg-green-600 text-white p-4 rounded-lg font-bold">{loading?'Setting...':'Set PIN'}</button></form></div></div>);}
